const todayOrders = [
  { menu: '아메리카노', price: 4000, cups: 2 },
  { menu: '라테', price: 4500, cups: 1 },
  { menu: '바닐라 라테', price: 5000, cups: 3 },
];

function closeDay(orders) {
  let todaySales = 0; // 오늘 매출: 쌓아 가는 칸
  let cupsMade = 0; // 만든 잔 수: 세어 가는 칸
  const waits = [];
  for (const order of orders) {
    let memo = order.price * order.cups; // 메모 칸 = 이 주문 금액
    todaySales += memo;
    cupsMade += order.cups;
    memo = order.cups * 2; // 같은 메모 칸 = 대기 시간(분)
    waits.push(memo + '분');
  }
  return `매출 ${todaySales}원 · ${cupsMade}잔 · 대기 ${waits.join(', ')}`;
}

console.log(closeDay(todayOrders));

