function closeDay(orders) {
  let todaySales = 0; // 오늘 매출: 쌓아 가는 칸
  let cupsMade = 0; // 만든 잔 수: 세어 가는 칸
  const waits = [];
  for (const order of orders) {
    const orderAmount = order.price * order.cups; // 주문 금액
    todaySales += orderAmount;
    cupsMade += order.cups;
    const waitMinutes = order.cups * 2; // 대기 시간(분)
