function receiptLine(orderedCups, coupons, price) {
  orderedCups = Math.max(orderedCups - coupons, 0); // 받은 잔 수를 덮어씀
  return `결제 ${orderedCups}잔 × ${price}원 = ${orderedCups * price}원`;
}

console.log(receiptLine(5, 1, 4500));
console.log(receiptLine(2, 3, 4000));

